import{_ as E,C as p,o as r,c as d,a5 as a,b as i,w as t,a as o,E as n,a7 as l}from"./chunks/framework.BmD0ICqc.js";const m=JSON.parse('{"title":"テクスチャのフィルタリングとミップマップ — 遠くの模様はなぜちらつく？","description":"","frontmatter":{"title":"テクスチャのフィルタリングとミップマップ — 遠くの模様はなぜちらつく？","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"斜めの床で1画素が覆うテクスチャ上の範囲を考え、ポイント、バイリニア、ミップマップ、異方性フィルタリングの違いを試す。","aliases":["テクスチャフィルタリング","サンプラー","テクセル","ポイントサンプリング","ニアレスト","バイリニア","ミップマップ","mipmap","トライリニア","異方性フィルタリング","anisotropic filtering","エイリアシング","モアレ","LOD"],"verification":"KhronosのWebGL 2.0・OpenGL ES 3.0・異方性フィルタリング拡張仕様に照合（2026-11-13）"}},"headers":[],"relativePath":"graphics/texture/texture-filtering-and-mipmaps.md","filePath":"graphics/texture/texture-filtering-and-mipmaps.md"}'),h={name:"graphics/texture/texture-filtering-and-mipmaps.md"};function c(A,e,_,g,B,u){const s=p("Mermaid");return r(),d("div",null,[e[2]||(e[2]=a('<h1 id="テクスチャのフィルタリングとミップマップ-—-遠くの模様はなぜちらつく" tabindex="-1">テクスチャのフィルタリングとミップマップ — 遠くの模様はなぜちらつく？ <a class="header-anchor" href="#テクスチャのフィルタリングとミップマップ-—-遠くの模様はなぜちらつく" aria-label="Permalink to &quot;テクスチャのフィルタリングとミップマップ — 遠くの模様はなぜちらつく？&quot;">​</a></h1><p>白黒の細かい模様を床に貼り、斜めから見ます。手前では模様の一つひとつが見えます。遠くでは線が太く見えたり、カメラを少し動かすだけで模様が明滅したりします。<strong>画面の1画素に、テクスチャのどれだけの範囲が入るか</strong>を考えると、サンプラーの設定で見え方が変わる理由が分かります。</p><p><a href="/study/practice/graphics/texture-filtering-observation.html">斜めの床でフィルタリングを比べる実践</a>では、4種類を同じ模様で試せます。</p><h2 id="_1画素では細かい模様を表しきれない" tabindex="-1">1画素では細かい模様を表しきれない <a class="header-anchor" href="#_1画素では細かい模様を表しきれない" aria-label="Permalink to &quot;1画素では細かい模様を表しきれない&quot;">​</a></h2><p>テクスチャ上の一つの画素を<strong>テクセル</strong>と呼びます。<a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン</a>では、三角形の内側で補間したUVをフラグメントシェーダーへ渡し、テクスチャを読みます。手前の床では、画面の1画素がテクスチャの狭い範囲を覆います。遠くの床では、同じ1画素に何個ものテクセルが入ります。</p><p>遠くの白黒模様の色を一点だけで決めると、模様の多くを取りこぼします。カメラが少し動いて一点のサンプルが黒から白に移ると、その画素が急に明るくなります。画面の解像度で細かな変化を表しきれず、別の模様やちらつきに見える現象が<strong>エイリアシング</strong>です。</p>',6)),(r(),i(l,null,{default:t(()=>[n(s,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E3%82%AB%E3%83%A1%E3%83%A9%E4%BD%8D%E7%BD%AE%20A%3Cbr%2F%3E%E7%94%BB%E7%B4%A0%E3%81%AE%E7%AF%84%E5%9B%B2%20%E2%96%A0%20%E2%96%A1%20%E2%96%A0%20%E2%96%A1%22%5D%20--%3E%20B%5B%22%E4%B8%80%E7%82%B9%E3%82%92%E8%AA%AD%E3%82%80%E3%81%A8%E9%BB%92%20%E2%96%A0%22%5D%0A%20%20%20%20C%5B%22%E3%82%AB%E3%83%A1%E3%83%A9%E4%BD%8D%E7%BD%AE%20B%3Cbr%2F%3E%E7%94%BB%E7%B4%A0%E3%81%AE%E7%AF%84%E5%9B%B2%20%E2%96%A1%20%E2%96%A0%20%E2%96%A1%20%E2%96%A0%22%5D%20--%3E%20D%5B%22%E4%B8%80%E7%82%B9%E3%82%92%E8%AA%AD%E3%82%80%E3%81%A8%E7%99%BD%20%E2%96%A1%22%5D%0A%20%20%20%20B%20--%3E%20E%5B%22%E7%94%BB%E9%9D%A2%E3%81%A7%E3%81%AF%E9%BB%92%E3%81%8B%E3%82%89%E7%99%BD%E3%81%B8%E5%A4%89%E3%82%8F%E3%82%8B%22%5D%0A%20%20%20%20D%20--%3E%20E%0A%20%20%20%20A%20--%3E%20F%5B%22%E7%AF%84%E5%9B%B2%E5%85%A8%E4%BD%93%E3%82%92%E3%81%AA%E3%82%89%E3%81%99%E3%81%A8%E7%81%B0%E8%89%B2%E3%81%AB%E8%BF%91%E3%81%A5%E3%81%8F%22%5D%0A%20%20%20%20C%20--%3E%20F%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a('<p>図では白黒が同じ割合で入る範囲を考えています。実際の色は、模様の分布とフィルターの重みに応じて変わります。画素が覆う範囲を考慮して細かい変化をならすと、カメラを動かしたときの色の跳びを抑えられます。</p><h2 id="元画像をポイントとバイリニアで読む" tabindex="-1">元画像をポイントとバイリニアで読む <a class="header-anchor" href="#元画像をポイントとバイリニアで読む" aria-label="Permalink to &quot;元画像をポイントとバイリニアで読む&quot;">​</a></h2><p><strong>ポイントサンプリング</strong>（ニアレスト）は、指定したUVに最も近いテクセルを一つ読みます。色の境界をぼかさず拡大したい絵に使えます。<strong>バイリニア</strong>は、同じ解像度の画像から周囲の4テクセルを取り、横と縦の位置に応じて重みを付けます。テクセルの境界で色が急に切り替わりにくくなります。</p><p>この実践のポイントとバイリニアでは、どちらも元画像を使います。画面の1画素が元画像の十数テクセルをまたぐとき、周囲4個だけでは、離れた場所にある白黒まで十分に反映できません。遠くを安定して描くには、読み取る解像度も変えます。 <a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">OpenGL ES 3.0仕様のテクスチャフィルター</a></p><h2 id="ミップマップは縮小した画像を使い分ける" tabindex="-1">ミップマップは縮小した画像を使い分ける <a class="header-anchor" href="#ミップマップは縮小した画像を使い分ける" aria-label="Permalink to &quot;ミップマップは縮小した画像を使い分ける&quot;">​</a></h2><p><strong>ミップマップ</strong>は、同じ画像を段階的に縮小して用意したものです。元画像が256×256なら、レベル0が256×256、レベル1が128×128、レベル2が64×64です。小さい画像では、一つのテクセルが元画像の広い範囲の色を反映します。</p>',6)),(r(),i(l,null,{default:t(()=>[n(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E3%83%AC%E3%83%99%E3%83%AB0%3Cbr%2F%3E256%20%C3%97%20256%22%5D%20--%3E%20B%5B%22%E3%83%AC%E3%83%99%E3%83%AB1%3Cbr%2F%3E128%20%C3%97%20128%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E3%83%AC%E3%83%99%E3%83%AB2%3Cbr%2F%3E64%20%C3%97%2064%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E4%BB%A5%E9%99%8D%E3%82%82%E6%AE%B5%E9%9A%8E%E7%9A%84%E3%81%AB%E7%B8%AE%E5%B0%8F%22%5D%0A%20%20%20%20P%5B%221%E7%94%BB%E7%B4%A0%E3%81%8C%E5%85%83%E7%94%BB%E5%83%8F%E3%81%AE%3Cbr%2F%3E%E7%B4%844%20%C3%97%204%E3%83%86%E3%82%AF%E3%82%BB%E3%83%AB%E3%82%92%E8%A6%86%E3%81%86%E4%BE%8B%22%5D%20--%3E%20C%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a('<p>隣の画素へ移ったときのUVの変化をもとに、GPUはテクスチャがどの程度縮小されているかを見積もります。そこから読み取る解像度を決める値が<strong>LOD</strong>です。例えば元画像の約4×4テクセルが1画素に入る場面では、縦横が4分の1になったレベル2が目安です。</p><p>実践の<strong>トライリニア</strong>は、LODに近い2レベルをそれぞれバイリニアで読み、その結果をさらに混ぜます。カメラの距離が変わり、使うレベルが移るときの境目も滑らかになります。WebGL 2の <code>generateMipmap</code> で縮小画像を作れます。どのレベルをメモリに置いておくかは、<a href="/study/graphics/texture/texture-streaming-and-mip-residency.html">テクスチャストリーミングとmipの常駐</a>で扱います。 <a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">OpenGL ES 3.0仕様のLODとミップマップ</a> · <a href="https://registry.khronos.org/webgl/specs/latest/2.0/" target="_blank" rel="noreferrer">WebGL 2.0仕様</a></p><h2 id="斜めの床では覆う範囲が細長くなる" tabindex="-1">斜めの床では覆う範囲が細長くなる <a class="header-anchor" href="#斜めの床では覆う範囲が細長くなる" aria-label="Permalink to &quot;斜めの床では覆う範囲が細長くなる&quot;">​</a></h2><p>床を浅い角度で見ると、1画素に入るテクスチャの範囲が、奥行き方向には長く、横方向には短くなることがあります。例えば、元画像で横2テクセル・奥行き16テクセルを覆う場合です。両方向を同じ尺度で扱い、16テクセルに近い縮小レベルを使うと、横方向の細かな模様もぼけます。</p><p><strong>異方性フィルタリング</strong>は、このように方向によって範囲の広さが違う場合に、細長い範囲に合わせてサンプルを組み合わせます。遠くの床では、ちらつきを抑えながら横方向の模様が残る場合があります。具体的な取り方やサンプル数は実装に依存します。実践では拡張 <code>EXT_texture_filter_anisotropic</code> が使える環境で、上限の範囲内で異方性を指定します。 <a href="https://registry.khronos.org/webgl/extensions/EXT_texture_filter_anisotropic/" target="_blank" rel="noreferrer">KhronosのWebGL拡張仕様</a> · <a href="https://registry.khronos.org/OpenGL/extensions/EXT/EXT_texture_filter_anisotropic.txt" target="_blank" rel="noreferrer">異方性フィルタリングの仕様</a></p><h2 id="_4種類を同じ床で比べる" tabindex="-1">4種類を同じ床で比べる <a class="header-anchor" href="#_4種類を同じ床で比べる" aria-label="Permalink to &quot;4種類を同じ床で比べる&quot;">​</a></h2><table tabindex="0"><thead><tr><th>選ぶモード</th><th>縮小時の設定</th><th>見比べる箇所</th></tr></thead><tbody><tr><td>ポイント</td><td><code>NEAREST</code></td><td>手前の模様の角と、動かしたときの遠くのちらつき</td></tr><tr><td>バイリニア</td><td><code>LINEAR</code></td><td>手前の境目が滑らかになり、遠くで残る細かな変化</td></tr><tr><td>トライリニア（ミップマップ）</td><td><code>LINEAR_MIPMAP_LINEAR</code></td><td>遠くの模様の安定と、斜めの部分のぼけ</td></tr><tr><td>異方性</td><td>トライリニアに異方性の設定を加える</td><td>斜めの床で、ぼけ方と模様の残り方がどう変わるか</td></tr></tbody></table><p>まずカメラを停止したまま切り替え、次に<strong>カメラを横に動かす</strong>を有効にして見比べます。位置が同じときのぼけと、動かしたときのちらつきの両方を観察できます。 <a href="/study/practice/graphics/texture-filtering-observation.html">ブラウザー実践を開く</a></p><p><a href="/study/samples/graphics/texture-filtering-observation/index.html" target="_self">比較デモを直接開く</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>遠くの白黒模様を一点で読むと、カメラを少し動かしただけでなぜちらつきますか。</p><details class="details custom-block"><summary>解答</summary><p>1画素の範囲に白と黒が入っていても、一点では片方だけを読みます。位置が少しずれて反対側の色を拾うと、画素の明るさが変わります。</p></details></li><li><p>バイリニアとトライリニアは、どの画像から色を読みますか。</p><details class="details custom-block"><summary>解答</summary><p>この実践のバイリニアは元画像の周囲4テクセルを読みます。トライリニアはLODに近い2つのミップレベルをバイリニアで読み、その結果も混ぜます。</p></details></li><li><p>斜めの床で異方性フィルタリングが役立つのは、1画素がテクスチャ上でどんな範囲を覆うときですか。</p><details class="details custom-block"><summary>解答</summary><p>一方向に広く、もう一方に狭い、細長い範囲を覆うときです。その形に合わせてサンプルを組み合わせると、短い方向の模様を残しやすくなります。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアル・テクスチャ・シェーダーの基本</a>で、テクスチャ、UV、サンプラーの担当を整理する。</li><li><a href="/study/graphics/pipeline/rasterization.html">ラスタライゼーション</a>で、三角形とUVが画面のサンプルにつながる段階を確認する。</li><li><a href="/study/graphics/postprocess/antialiasing.html">アンチエイリアシング</a>で、床模様のちらつきとポリゴンの輪郭のギザギザを比べる。</li><li><a href="/study/learn/roadmap.html?node=gfx-pipeline#graphics">3DCG・描画ロードマップの「レンダリングパイプライン」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://registry.khronos.org/webgl/specs/latest/2.0/" target="_blank" rel="noreferrer">Khronos — WebGL 2.0 Specification</a> · <a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">OpenGL ES 3.0.6 Specification</a></li><li><a href="https://registry.khronos.org/webgl/extensions/EXT_texture_filter_anisotropic/" target="_blank" rel="noreferrer">Khronos — WebGL EXT_texture_filter_anisotropic</a> · <a href="https://registry.khronos.org/OpenGL/extensions/EXT/EXT_texture_filter_anisotropic.txt" target="_blank" rel="noreferrer">OpenGL EXT_texture_filter_anisotropic</a></li></ul>',15))])}const b=E(h,[["render",c]]);export{m as __pageData,b as default};
